import json,collections,sys,os
D='/tmp/ex/'
def load(f): return [json.loads(l) for l in open(D+f+'.ndjson')]
res={t:load(t) for t in ['Patient','Condition','Observation','Specimen','Basic','MedicationAdministration','MedicationDispense','DocumentReference','Task','AllergyIntolerance','EpisodeOfCare']}
pats={p['id']:p for p in res['Patient']}
def mrn(p): return p['identifier'][0]['value']
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
bypat=collections.defaultdict(list)
for t,rs in res.items():
    for r in rs:
        s=r.get('subject') or r.get('patient') or r.get('for')
        if s and 'reference' in s:
            bypat[s['reference'].split('/')[1]].append(r)
acc=collections.defaultdict(list)
for b in res['Basic']:
    acc[ext(b,'accession')].append(b)
specs={s['id']:s for s in res['Specimen']}
obs_by_spec=collections.defaultdict(list)
for o in res['Observation']:
    if o.get('specimen'): obs_by_spec[o['specimen']['reference'].split('/')[1]].append(o)
epi={e['id']:e for e in res['EpisodeOfCare']}
def etime(r): return ext(r,'event-time') or ''

def label(pid):
    p=pats[pid]; return f"{p['name'][0]['text']} MRN {mrn(p)} DOB {p['birthDate']} {p['gender']}"

def dump(pid,out):
    p=pats[pid]
    w=out.write
    w(f"### PATIENT {pid}: {label(pid)}\n")
    for e in res['EpisodeOfCare']:
        if e['patient']['reference'].endswith(pid): w(f"  EPISODE {e['id']} dx_start={e['period']['start']} type={e['type'][0]['text']}\n")
    rs=sorted(bypat[pid],key=lambda r: (etime(r) or r.get('authoredOn','')))
    for r in rs:
        t=r['resourceType']; et=etime(r) or r.get('authoredOn','')
        if t=='EpisodeOfCare': continue
        if t=='Condition':
            w(f"  [{et}] Condition {r['id']}: {r['code']['text']} recorder={r.get('recorder',{}).get('display')}\n")
        elif t=='AllergyIntolerance':
            w(f"  [{et}] Allergy {r['id']}: {r['code']['text']} {[m['text'] for rx in r.get('reaction',[]) for m in rx['manifestation']]}\n")
        elif t=='MedicationAdministration':
            w(f"  [{et}] MedAdmin {r['id']}: {r['medicationCodeableConcept']['text']} | {r['dosage']['text']} | {r['status']} | {[n['text'] for n in r.get('note',[])]}\n")
        elif t=='MedicationDispense':
            w(f"  [{et}] MedDispense {r['id']}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} | {[d['text'] for d in r.get('dosageInstruction',[])]} | {[n['text'] for n in r.get('note',[])]}\n")
        elif t=='Specimen':
            ln,lm,ld=ext(r,'label-name'),ext(r,'label-mrn'),ext(r,'label-dob')
            match = (lm==mrn(p) and ld==p['birthDate'])
            a=r['accessionIdentifier']['value']
            w(f"  [{et}] Specimen {r['id']}: acc={a} coll={r['collection']['collectedDateTime']} by {r['collection'].get('collector',{}).get('display')} label=({ln}|{lm}|{ld}) {'LABEL_OK' if match else '*** LABEL_MISMATCH'}\n")
            for b in acc.get(a,[]):
                bm=(ext(b,'patient-mrn')==mrn(p) and ext(b,'patient-dob')==p['birthDate'])
                w(f"      accessioning {b['id']} [{etime(b)}] author={b['author']['display']} ({ext(b,'patient-name')}|{ext(b,'patient-mrn')}|{ext(b,'patient-dob')}) recv={ext(b,'received')} {'ACC_OK' if bm else '*** ACC_MISMATCH'}\n")
            for o in obs_by_spec.get(r['id'],[]):
                if not o['subject']['reference'].endswith(pid):
                    w(f"      !! observation on this specimen belongs to other patient {o['subject']['reference']} {o['id']} {o['code']['text']} {o.get('valueString')}\n")
        elif t=='Observation':
            sp=o_sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            extra=''
            if sp and sp in specs:
                s=specs[sp]
                if not s['subject']['reference'].endswith(pid): extra+=f" !!SPEC_OF_OTHER({s['subject']['reference']})"
                if ext(s,'label-mrn')!=mrn(p) or ext(s,'label-dob')!=p['birthDate']: extra+=f" !!SPECLABEL({ext(s,'label-name')}|{ext(s,'label-mrn')}|{ext(s,'label-dob')})"
            a=(r.get('identifier') or [{}])[0].get('value')
            for b in acc.get(a,[]):
                if ext(b,'patient-mrn')!=mrn(p) or ext(b,'patient-dob')!=p['birthDate']:
                    extra+=f" !!ACC({ext(b,'patient-name')}|{ext(b,'patient-mrn')}|{ext(b,'patient-dob')})"
            w(f"  [{et}] Obs {r['id']}: {r['code']['text']} = {r.get('valueString')} [{r['status']}] coll={r.get('effectiveDateTime')} issued={r.get('issued')} acc={a} spec={sp} notes={[n['text'] for n in r.get('note',[])]}{extra}\n")
        elif t=='DocumentReference':
            w(f"  [{et}] Doc {r['id']} ({r['type']['text']}) author={[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')}:\n      {r['description'].replace(chr(10),' / ')}\n")
        elif t=='Task':
            if r['status']=='requested':
                w(f"  [{et}] REQUEST {r['id']} {r['code']['coding'][0]['code']} focus={r['focus']['reference']}: {r['description']}\n")
            else:
                w(f"  [{et}] ITEM {r['id']} {r['code']['coding'][0]['code'] if r.get('code') else ''} {r.get('businessStatus')}\n")
    w("\n")
if __name__=='__main__':
    order=sorted(pats)
    with open('/tmp/w/all.txt','w') as f:
        for pid in order: dump(pid,f)
